create table if not exists public.asaas_cobrancas (id uuid primary key default gen_random_uuid(), fatura_id uuid not null unique references public.faturas(id) on delete cascade, asaas_customer_id text not null, asaas_payment_id text not null unique, status text not null, valor numeric(14,2) not null, invoice_url text, bank_slip_url text, linha_digitavel text, codigo_pix text, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.asaas_transferencias (id uuid primary key default gen_random_uuid(), cobranca_id uuid not null unique references public.asaas_cobrancas(id) on delete cascade, asaas_transfer_id text not null unique, valor numeric(14,2) not null, status text not null, destino_mascarado text, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.asaas_eventos (id uuid primary key default gen_random_uuid(), evento_id text not null unique, tipo text not null, payload jsonb not null, recebido_em timestamptz not null default now());
alter table public.asaas_cobrancas enable row level security; alter table public.asaas_transferencias enable row level security; alter table public.asaas_eventos enable row level security;
